metanorma-extension.source-highlighter-css:
sourcecode table td { padding: 5px; }
sourcecode table pre { margin: 0; }
sourcecode, sourcecode .w {
  color: #444444;
}
sourcecode .cp {
  color: #CC00A3;
}
sourcecode .cs {
  color: #CC00A3;
}
sourcecode .c, sourcecode .ch, sourcecode .cd, sourcecode .cm, sourcecode .cpf, sourcecode .c1 {
  color: #FF0000;
}
sourcecode .kc {
  color: #C34E00;
}
sourcecode .kd {
  color: #0000FF;
}
sourcecode .kr {
  color: #007575;
}
sourcecode .k, sourcecode .kn, sourcecode .kp, sourcecode .kt, sourcecode .kv {
  color: #0000FF;
}
sourcecode .s, sourcecode .sb, sourcecode .sc, sourcecode .ld, sourcecode .sd, sourcecode .s2, sourcecode .se, sourcecode .sh, sourcecode .si, sourcecode .sx, sourcecode .sr, sourcecode .s1, sourcecode .ss {
  color: #009C00;
}
sourcecode .sa {
  color: #0000FF;
}
sourcecode .nb, sourcecode .bp {
  color: #C34E00;
}
sourcecode .nt {
  color: #0000FF;
}

sourcecode.body:
{%assign g_type = "enumeration"%}
{%assign g_def = "ICEBRS specifies the concentrations of very thick brash (&quot;AV&quot;), thick brash (&quot;AK&quot;), medium brash (&quot;AM&quot;) and thin brash ice (&quot;AT&quot;)."%}
{%assign g_vals = "01:0/10 – 1/10 | 10:1/10 | 12:1/10 – 2/10 | 20:2/10 | 23:2/10 – 3/10 | 30:3/10 | 34:3/10 – 4/10 | 40:4/10 | 45:4/10 – 5/10 | 50:5/10 | 56:5/10 – 6/10 | 60:6/10 | 67:6/10 – 7/10 | 70:7/10 | 78:7/10 – 8/10 | 80:8/10 | 89:8/10 – 9/10 | 90:9/10 | 91:9/10 – 10/10 | 92:10/10 | 98:No Brash ice | 99:Undetermined/Unknown" | split: " | "%}
{%for p1 in context.packages%}{%for p2 in p1.packages%}{%for e in p2.enums%}
{%if e.name == "brashIce"%}
{%assign g_found = true%}
{%if e.values.size != g_vals.size%}MODEL MISMATCH {{e.name}}: model {{e.values.size}} vs page {{g_vals.size}}{%endif%}
[cols="a",options="headers,unnumbered"]
|===
a| [underline]#**IHO Definition** :# {{g_def}}

a| [underline]#**Attribute Type :**# {{g_type}}

{%for v in g_vals%}{%assign pair = v | split: ":"%}
. {{pair.first}} +
[underline]#**IHO Definition**# :{{pair.last}}

{%endfor%}|===
{%endif%}
{%endfor%}{%endfor%}{%endfor%}
{%if g_found == false%}MODEL MISMATCH: brashIce not found in the EA model{%endif%}

